    TAccountSignerTokenAccount,
    TAccountLiquidityVaultAuthority,
    TAccountLiquidityVault,
    TAccountMint,
    TAccountIntegrationAcc1,
    TAccountFTokenMint,
    TAccountIntegrationAcc2,
    TAccountLendingAdmin,
    TAccountSupplyTokenReservesLiquidity,
    TAccountLendingSupplyPositionOnLiquidity,
